namespace Vnecoms\VendorsCms\Model\Rewrite;

use Magento\Store\Model\StoreManagerInterface;
use Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory;

class CmsPageUrlRewriteGenerator
{
    /**
     * Entity type code.
     */
    const ENTITY_TYPE = 'vendor-cms-page';

    /** @var \Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory */
    protected $urlRewriteFactory;

    /** @var \Vnecoms\VendorsCms\Model\Rewrite\CmsPageUrlPathGenerator */
    protected $cmsPageUrlPathGenerator;

    /**
     * Store manager.
     *
     * @var StoreManagerInterface
     */
    protected $storeManager;

    /**
     * @var \Vnecoms\VendorsCms\Model\Page
     */
    protected $cmsPage;

    /**
     * @var \Vnecoms\Vendors\Model\Session
     */
    protected $vendorSession;

    /**
     * @param \Magento\UrlRewrite\Service\V1\Data\UrlRewriteFactory     $urlRewriteFactory
     * @param \Vnecoms\VendorsCms\Model\Rewrite\CmsPageUrlPathGenerator $cmsPageUrlPathGenerator
     * @param StoreManagerInterface                                     $storeManager
     */
    public function __construct(
        UrlRewriteFactory $urlRewriteFactory,
        CmsPageUrlPathGenerator $cmsPageUrlPathGenerator,
        StoreManagerInterface $storeManager
    ) {
        $this->urlRewriteFactory = $urlRewriteFactory;
        $this->storeManager = $storeManager;
        $this->cmsPageUrlPathGenerator = $cmsPageUrlPathGenerator;
    }

    /**
     * @param \Vnecoms\VendorsCms\Model\Page $cmsPage
     *
     * @return \Magento\UrlRewrite\Service\V1\Data\UrlRewrite[]
     */
    public function generate($cmsPage)
    {
        $this->cmsPage = $cmsPage;
        $urls = $this->generateForAllStores();
        $this->cmsPage = null;

        return $urls;
    }

    /**
     * Generate list of urls for default store.
     *
     * @return \Magento\UrlRewrite\Service\V1\Data\UrlRewrite[]
     */
    protected function generateForAllStores()
    {
        $urls = [];
        foreach ($this->storeManager->getWebsite($this->getVendor()->getWebsiteId())->getStoreIds() as $storeId) {
            $urls[] = $this->createUrlRewrite($storeId);
        }

        return $urls;
    }

    /**
     * Create url rewrite object.
     *
     * @param int $storeId
     * @param int $redirectType
     *
     * @return \Magento\UrlRewrite\Service\V1\Data\UrlRewrite
     */
    protected function createUrlRewrite($storeId, $redirectType = 0)
    {
        return $this->urlRewriteFactory->create()->setStoreId($storeId)
            ->setEntityType(self::ENTITY_TYPE)
            ->setEntityId($this->cmsPage->getId())
            ->setRequestPath($this->cmsPage->getIdentifier())
            ->setTargetPath($this->cmsPageUrlPathGenerator->getCanonicalUrlPath($this->cmsPage))
            ->setIsAutogenerated(1)
            ->setRedirectType($redirectType);
    }

    public function getVendor()
    {
        return ($this->vendorSession != null) ? $this->vendorSession->getVendor() : \Magento\Framework\App\ObjectManager::getInstance()
            ->get('Vnecoms\Vendors\Model\Session')->getVendor();
    }
}
